% --- Vehicle Parameters ---
Mv = 285.763;                   % Vehicle Weight                     (kg)
r = 0.203;                      % Wheel Radius                       (m)
J = 1.2;                        % ESTIMATED Total Rotational Inertia (kg*m^2)
J_Motor = 0.25;                 % ESTIMATED Motor Rotational Inertia (kg*m^2)
J_Wheel = 0.165;                % ESTIMATED Wheel Rotational Inertia (kg*m^2)
K = 2552;                       % Half-Shaft Stiffness               (Nm/rad)
C = 30;                         % Half-Shaft Damping                 (Nms/rad)
fd = 4.5;                       % Final Drive motor:tire             (Ratio)
h_cg = 0.25273;                 % Height of Center of Gravity        (m)
W = 1.53035;                    % Wheelbase                          (m)
Grip_Fact = 1.0;                % Grip Factor of the Tire
Grip_Influence = 1.2;           % Grip Factor Impact on Table
Drive_Train = 0.89;             % Drivetain loss perecent         


% --- Aerodynamics ---
A = 1;                          % Frontal Area                       (m^2)
rho = 1.225;                    % Air Density                        (kg/m^3)
Cd = 1;                         % Drag Coefficient
Cl = 3.8;                       % Lift Coefficient
Cp = 0.53;                      % Load Percent on Rear Wheels Aero

% -- Static Loads --
cg_f = 0.734568;                % Front Axel to CG                   (m)

% -- Control Params --
Slip_Target = 0.13;             % Target Slip Ratio
T_request = 150;                % Initial Driver Torque Request      (Nm)
%Switch = 3.0;                  % Velocity to Change Controllers     (m/s)
Start_Blend = 3.0;              % Velocity Low Start to Change PIDs  (m/s)
End_Blend = 8.0;                % Velocity High End Changing PIDs    (m/s)
Max_Wheel_Omega = 183.3;        % Maximum Wheel Angular Velocity     (rad/s)
Max_Motor_Torque = 150;         % Maximum Motor Torque               (rad/s)
gravity = 9.80665;              % Accel due to Gravity Used          (m/s^2)

% -- PID Params Slip Ratio --
P = 1.75;                       % Proportional in PID
I = 4;                          % Integral in PID
D = 0;                          % Derivative in PID
Ts = 0.01;                      % Sample Time                        (s)


% -- Simulink --
timedomain = 10;                % Simulation Time (s)
simout = sim("TC_SIM.slx", timedomain);

% -- Time and Data --
Time = simout.v_velocity.Time;           % Time Vector                   (s)
Wheel_Speed = simout.wheel_speed.Data;   % Wheel Speed                   (m/s)
Lift = simout.v_lift.Data;               % Vechile Lift                  (N)
Drag = simout.v_drag.Data;               % Vechile Drag                  (N)
Trac = simout.Longitudinal_Force.Data;   % Tractive Force                (N)
Accel = simout.v_accel.Data;             % Vechicle Accel                (m/s^2)
Vel = simout.v_velocity.Data;            % Vechicle Velocity             (m/s)
Dist = simout.v_distance.Data;           % Vechicle Distance             (m)
Motor_Tor = simout.T_motor.Data;         % Motor Torque                  (Nm)
Normal_Force = simout.normal_force.Data; % Normal Force on the rear axel (N)
Error = simout.error.Data;               % PID Error
Mu = simout.mu.Data;                     % Friction Coefficient
Slip_Ratio = simout.slip_ratio.Data;     % Slip Ratio
Max_Motor_Tor = simout.Max_Tor.Data;     % Max Motor torque              (Nm)
PID = simout.pid_correction.Data;        % The PID Correction



% -- Print Time when Distance is 75 m --
target_distance = 75; % Target distance (m)
time_at_target_distance = Time(Dist >= target_distance); % Find times when distance is greater than or equal to 75 m

if ~isempty(time_at_target_distance) %[output:group:69f50b46]
    fprintf('Time when distance reaches 75 m: %.4f seconds\n', time_at_target_distance(1)); %[output:7fdecd7f]
else
    fprintf('Distance of 75 m was not reached during the simulation.\n');
end %[output:group:69f50b46]

% -- Print Time when Speed is 26.8224 m/s --
target_speed = 26.8224; % Target speed (m/s)
time_at_target_speed = Time(Vel >= target_speed); % Find times when speed is greater than or equal to 26.8224 m/s

if ~isempty(time_at_target_speed) %[output:group:4ee9aeb8]
    fprintf('Time when speed reaches 26.8224 m/s: %.4f seconds\n', time_at_target_speed(1)); %[output:9740056e]
else
    fprintf('Speed of 26.8224 m/s was not reached during the simulation.\n');
end %[output:group:4ee9aeb8]

% --- Black-on-white figure theme (applies to all figures in this session) ---
set(groot, ...
    'defaultFigureColor',   'white', ...
    'defaultAxesColor',     'white', ...
    'defaultAxesXColor',    'black', ...
    'defaultAxesYColor',    'black', ...
    'defaultAxesZColor',    'black', ...
    'defaultTextColor',     'black', ...
    'defaultAxesGridColor', 'black');

% -- Figure output settings --
outdir = fullfile(pwd, 'figures');
if ~exist(outdir, 'dir'); mkdir(outdir); end

% Helper to export the current figure and write CSV of the series used.
save_fig = @(base, X, Y, xname, ynames) export_pdf_png_and_csv(gcf, outdir, base, X, Y, xname, ynames);

% PID
figure;  %[output:07927f74]
plot(Time, PID, 'k', 'LineWidth', 2); %[output:07927f74]
title('PID Output'); %[output:07927f74]
xlabel('Time (s)'); ylabel('PID'); %[output:07927f74]
xlim([0, 1.8]); %[output:07927f74]
grid on; %[output:07927f74]
save_fig('pid', Time, PID, 'Time_s', {'PID'}); %[output:07927f74]
% Slip Ratio
figure; %[output:499ea002]
plot(Time, Slip_Ratio, 'k', 'LineWidth', 2); %[output:499ea002]
title(sprintf('Slip Ratio (%.2f Grip Factor)', Grip_Fact)); %[output:499ea002]
xlabel('Time (s)'); ylabel('Slip Ratio'); %[output:499ea002]
%ylim([0, 0.2]); 
xlim([0, 10]); %[output:499ea002]
grid on; %[output:499ea002]
save_fig('slip_ratio', Time, Slip_Ratio, 'Time_s', {'Slip_Ratio'}); %[output:499ea002]


% Error
figure;  %[output:1b1bdf11]
plot(Time, Error, 'k', 'LineWidth', 2); %[output:1b1bdf11]
title(sprintf('Error (%.2f Grip Factor)', Grip_Fact)); %[output:1b1bdf11]
xlabel('Time (s)'); ylabel('Error'); %[output:1b1bdf11]
xlim([0, 1.8]); %[output:1b1bdf11]
grid on; %[output:1b1bdf11]
save_fig('error', Time, Error, 'Time_s', {'Error'}); %[output:1b1bdf11]


% Distance
figure; %[output:8b0e5e2a]
plot(Time, Dist, 'k', 'LineWidth', 2); %[output:8b0e5e2a]
title(sprintf('Distance (%.2f Grip Factor)', Grip_Fact)); %[output:8b0e5e2a]
xlabel('Time (s)'); ylabel('Distance (m)'); %[output:8b0e5e2a]
grid on; %[output:8b0e5e2a]
save_fig('distance', Time, Dist, 'Time_s', {'Distance_m'}); %[output:8b0e5e2a]

% Velocity
figure; %[output:108fe85a]
plot(Time, Vel, 'k', 'LineWidth', 2); %[output:108fe85a]
title(sprintf('Velocity (%.2f Grip Factor)', Grip_Fact)); %[output:108fe85a]
xlabel('Time (s)'); ylabel('Velocity (m/s)'); %[output:108fe85a]
grid on; %[output:108fe85a]
save_fig('velocity', Time, Vel, 'Time_s', {'Velocity_mps'}); %[output:108fe85a]

% Acceleration
figure; %[output:3eb069f7]
plot(Time, Accel, 'k', 'LineWidth', 2); %[output:3eb069f7]
title(sprintf('Acceleration (%.2f Grip Factor)', Grip_Fact)); %[output:3eb069f7]
xlabel('Time (s)'); ylabel('Accel (m/s^2)'); %[output:3eb069f7]
%ylim([0, 12]);
grid on; %[output:3eb069f7]
save_fig('acceleration', Time, Accel, 'Time_s', {'Acceleration_mps2'}); %[output:3eb069f7]




% Normal Force
figure; %[output:49c788d4]
plot(Time, Normal_Force, 'k', 'LineWidth', 2); %[output:49c788d4]
title(sprintf('Normal Force on Rear Axle (%.2f Grip Factor)', Grip_Fact)); %[output:49c788d4]
xlabel('Time (s)'); ylabel('Normal Force (N)'); %[output:49c788d4]
ylim([0, 3500]); %[output:49c788d4]
grid on; %[output:49c788d4]
save_fig('normal_force', Time, Normal_Force, 'Time_s', {'Normal_Force_N'}); %[output:49c788d4]

% Target Motor Torque
figure; %[output:8dd2bc20]
plot(Time, Motor_Tor, 'k', 'LineWidth', 2); %[output:8dd2bc20]
title(sprintf('Target Motor Torque PID (%.2f Grip Factor)', Grip_Fact)); %[output:8dd2bc20]
xlabel('Time (s)'); ylabel('Torque %'); %[output:8dd2bc20]
ylim([0, 1.1]); %[output:8dd2bc20]
grid on; %[output:8dd2bc20]
save_fig('target_motor_torque_PID_2', Time, Motor_Tor, 'Time_s', {'Motor_Torque_Nm'}); %[output:8dd2bc20]


% Tractive Force (Time)
figure; %[output:26bec6e0]
plot(Time, Trac, 'k', 'LineWidth', 2); %[output:26bec6e0]
title(sprintf('Tractive Force (%.2f Grip Factor)', Grip_Fact)); %[output:26bec6e0]
xlabel('Time (s)'); ylabel('Tractive Force (N)'); %[output:26bec6e0]
grid on; %[output:26bec6e0]
save_fig('tractive_force', Time, Trac, 'Time_s', {'Tractive_Force_N'}); %[output:26bec6e0]

% Mu (Time)
figure; %[output:5e7bbc6a]
plot(Time, Mu, 'k', 'LineWidth', 2); %[output:5e7bbc6a]
title(sprintf('Mu (%.2f Grip Factor)', Grip_Fact)); %[output:5e7bbc6a]
xlabel('Time (s)'); ylabel('mu'); %[output:5e7bbc6a]
grid on; %[output:5e7bbc6a]
save_fig('mu', Time, Mu, 'Time_s', {'Mu'}); %[output:5e7bbc6a]

% Tractive Force vs Slip Ratio (XY)
figure; %[output:12bde72d]
plot(Slip_Ratio, Trac, 'k', 'LineWidth', 2); %[output:12bde72d]
title(sprintf('Tractive Force vs. Slip Ratio (%.2f Grip Factor)', Grip_Fact)); %[output:12bde72d]
xlabel('Slip Ratio'); ylabel('Tractive Force (N)'); %[output:12bde72d]
xlim([0.0, 0.18]); %[output:12bde72d]
grid on; %[output:12bde72d]
save_fig('tractive_force_vs_slip_ratio', Slip_Ratio, Trac, 'Slip_Ratio', {'Tractive_Force_N'}); %[output:12bde72d]

% --- Combined plot: all series as torque at the wheel (ATW) ---
T_motor_atw    = Motor_Tor(:) * fd;      % motor target -> wheel torque (Nm)
T_from_trac_atw= Trac(:) * r;            % tractive force -> wheel torque (Nm)
max_avail_atw  = Max_Motor_Tor(:) * fd;  % max motor torque -> wheel torque (Nm)

figure; hold on; %[output:7a26f5a9]
p1 = plot(Time, T_motor_atw,     'LineWidth', 2); %[output:7a26f5a9]
p2 = plot(Time, T_from_trac_atw, 'LineWidth', 2); %[output:7a26f5a9]
p3 = plot(Time, max_avail_atw,   'g--', 'LineWidth', 2); %[output:7a26f5a9]
hold off; grid on; %[output:7a26f5a9]

title(sprintf('Wheel Torque Comparison (%.2f Grip Factor)', Grip_Fact)); %[output:7a26f5a9]
xlabel('Time (s)'); %[output:7a26f5a9]
ylabel('Wheel Torque (N·m)'); %[output:7a26f5a9]
legend([p1 p2 p3], ... %[output:7a26f5a9]
    {'Target torque ATW', 'Tractive force \rightarrow torque ATW', 'Max available motor torque ATW'}, ... %[output:7a26f5a9]
    'Location','northeast'); %[output:7a26f5a9]

allY = [T_motor_atw; T_from_trac_atw; max_avail_atw];
allY = allY(~isnan(allY));
if ~isempty(allY)
    ylim([0, 1.1*max(allY)]); %[output:7a26f5a9]
end

save_fig('torque_comparison_atw', Time, [T_motor_atw, T_from_trac_atw, max_avail_atw], ... %[output:group:51c7555c] %[output:7a26f5a9]
         'Time_s', {'Target_Torque_ATW_Nm','From_Tractive_Force_ATW_Nm','Max_Available_ATW_Nm'}); %[output:group:51c7555c] %[output:7a26f5a9]


function export_pdf_png_and_csv(hfig, outdir, base, X, Y, xname, ynames)
    % Ensure shapes
    X = X(:);
    if isvector(Y)
        Y = Y(:);
    end
    n = min(numel(X), size(Y,1));
    X = X(1:n);
    Y = Y(1:n, :);

    % Build table with clean variable names
    varNames = [{xname}, ynames(:)'];
    varNames = matlab.lang.makeValidName(varNames);
    T = array2table([X, Y], 'VariableNames', varNames);

    % Write CSV (same basename)
    writetable(T, fullfile(outdir, [base '.csv']));

    % Export vector PDF (same basename)
    exportgraphics(hfig, fullfile(outdir, [base '.pdf']), ...
        'BackgroundColor','white', 'ContentType','vector');

    % (Optional) also keep a PNG for quick viewing
    exportgraphics(hfig, fullfile(outdir, [base '.png']), ...
        'BackgroundColor','white', 'Resolution', 300); % ← delete if not needed
end

